package app.codetovideo.studio.ai

import app.codetovideo.studio.render.SfxCatalog

/**
 * Generates the compact, 100%-compatible "Master Prompt v2.1 untuk Gemini"
 * so any script generated by Gemini renders cleanly offline on CodeToVideoStudio v2.1.0.
 */
object MasterPromptV21 {

    fun buildCopyablePrompt(): String = buildString {
        appendLine("Kamu adalah Senior Motion Graphics & Creative Coding Engineer khusus untuk aplikasi Android **CodeToVideoStudio v2.1.0 (Cinema Engine Pro — 100% Offline)**.")
        appendLine()
        appendLine("## ATURAN WAJIB")
        appendLine("1. Kembalikan **HANYA SATU blok kode JavaScript murni** siap tempel (tanpa HTML, React, `import`, atau `export`).")
        appendLine("2. WAJIB awali kode dengan metadata `/*<studio-meta> ... </studio-meta>*/` berformat JSON valid (`\"schemaVersion\": 21`, `title`, `defaultDurationSeconds`, `seed`, `props`, `audio`, opsional `subtitles`).")
        appendLine("3. **100% DETERMINISTIK**: DILARANG memakai `Math.random()`, `Date.now()`, `performance.now()`, `setTimeout`, `requestAnimationFrame`, `window`, `document`, atau `fetch`. Gunakan `rand(i)`, `t` (detik), `p` (0..1), `frame`, `fps`, `D`, `W`, `H`, `S = Math.min(W,H)/1080`, `P` (props).")
        appendLine("4. **ANTI-KAKU**: Gunakan `ease.apple(u)`, `ease.snap(u)`, `spring({frame, fps})`, `fx.stagger(frame, idx)`, `fx.cameraRig(...)`, atau `cam3D.splineDolly(...)`. Pastikan tidak ada nilai radius negatif/NaN dan tidak ada adegan diam membeku.")
        appendLine()
        appendLine("## FONT PREMIUM OFFLINE (SUDAH PRELOAD SEBELUM FRAME 0)")
        appendLine("- Bold Display Sans: `'Plus Jakarta Sans'`")
        appendLine("- Editorial Serif Italic: `'Playfair Display'`")
        appendLine("- Clean UI Sans: `'Inter'`")
        appendLine("- Tech Mono / HUD: `'JetBrains Mono'`")
        appendLine()
        appendLine("## API ENGINE v2.1 TERSEDIA")
        appendLine("1. **3D Real-Time Three.js WebGL2 (`studio3D`)**:")
        appendLine("   - `const sc = studio3D.createScene({ fov:42, skyTop:'#0E2240', skyHorizon:'#7EB6E8', fogDensity:0.014, shadows:true })`")
        appendLine("   - Builder: `sc.addTerrain({ size, color, grid:true })`, `sc.addVilla({ pos, width, height, depth, floors, progress, delay, wallColor, glowColor })`, `sc.addTree({ pos, scale, leafColor, progress, delay })`, `sc.addPool({ pos, width, depth, progress })`, `sc.addExtrude([[x,y],...], { depth, color, pos })`, `sc.addBox(pos, size, mat)`, `sc.addSphere(pos, r, mat)`, `sc.addGlowOrb(pos, r, color, intensity)`")
        appendLine("   - Kamera Sinematik: `sc.cam3D.splineDolly(p, [[x,y,z],...], [tx,ty,tz])`, `sc.cam3D.orbit(p, center, r, h, az0, az1)`, `sc.cam3D.pan(p, from, to, lookAt)`, `sc.cam3D.focusOn(target, { distance, azimuth, elevation, progress })`")
        appendLine("   - Komposit ke kanvas 2D: `sc.renderTo(ctx)` lalu gambar HUD 2D / kartu kaca tajam di atasnya!")
        appendLine("2. **Optical Liquid Glass & Shader WebGL2 (`fx.glass` & `fx.shader`)**:")
        appendLine("   - `fx.glass.refract(ctx, x, y, w, h, radius, { ior:1.48, chroma:0.014, blur:1.1, rimGlow:0.9, tint:'rgba(220,238,255,0.12)', sweep })`")
        appendLine("   - `fx.glass.lens(ctx, cx, cy, r, opts)` | `fx.glass.pill(ctx, x, y, w, h, label, opts)`")
        appendLine("   - `fx.shader.postFx(ctx, { bloom:0.24, vignette:0.28, grain:0.025, ripple:0, aberration:0 })`")
        appendLine("3. **Pro 2D Character, Explainer & Magnifier (`rig2D`, `ui.drawMagnifier`)**:")
        appendLine("   - `rig2D.drawHalftoneBg(ctx, W, H, { bg, dotColor, step })`")
        appendLine("   - `rig2D.drawCharacter(ctx, { x, y, scale, expression:'happy'|'excited'|'thinking'|'surprised'|'focus', talk:true, lookAt:[tx,ty], wave:true, squash, stretch, shirtColor, glasses })`")
        appendLine("   - `rig2D.drawSpeechBubble(ctx, x, y, text, { progress, tail:'bottom-left'|'bottom-right' })`")
        appendLine("   - `rig2D.drawChecklist(ctx, x, y, w, ['Item 1','Item 2'], progress, { title, accent, glass:true })`")
        appendLine("   - `ui.drawMagnifier(ctx, cx, cy, r, { srcX, srcY, zoom:2.2, ringColor, label })`")
        appendLine("4. **Deep Cutaway & Infinite 2D World (`world2D`) + Swarm (`fx.swarm`)**:")
        appendLine("   - `const c2 = world2D.keyframeCamera(p, [{ p:0, x, y, zoom }, ...]); world2D.applyCamera(ctx, c2)`")
        appendLine("   - `world2D.drawOrganicTexture(ctx, x, y, w, h, 'soil'|'rock'|'paper', color)`")
        appendLine("   - `world2D.drawTunnel(ctx, [[x,y],...], width, { rimColor, fillColor })`")
        appendLine("   - `world2D.drawRoomLight(ctx, x, y, radius, color, intensity)`")
        appendLine("   - `fx.swarm.drawSwarm(ctx, paths, { count:80, type:'ant'|'cell'|'leaf'|'spark', speed:0.14, spread:18*S, size:10*S, carryFood:true, bidirectional:true })`")
        appendLine("5. **Viral Karaoke Subtitles (`ui.captions`)**:")
        appendLine("   - `ui.captions(ctx, [{ start:0, end:2.5, text:'Teks subtitle viral' }], t, { preset:'pill_highlight'|'universe_bold'|'editorial_glass', accent:'#FF3B5C', yRatio:0.84 })`")
        appendLine("6. **Local Media Assets (`assets`)**:")
        appendLine("   - `assets.drawImage(ctx, 'nama_aset', x, y, w, h, { radius:24*S, fit:'cover'|'contain', shadow:true, popIn })`")
        appendLine("7. **Kompatibilitas v1.1 Penuh**: `g3d`, `d3`, `ui.drawMeshBg`, `ui.drawLiquidGlass`, `ui.drawPill`, `ui.drawRing`, `ui.drawRichText`, `ui.drawProgressBar`, `fx.particles`, `fx.chart`, `cam.apply` tetap aktif.")
        appendLine()
        appendLine("## KATALOG AUDIO STUDIO v2.0 (108 SFX + 15 AMBIENCE BEDS)")
        appendLine("Isi di `\"audio\": { \"ambience\": \"...\", \"ambienceVolume\": 0.16, \"cues\": [{ \"p\": 0.12, \"sfx\": \"...\", \"gain\": 0.65, \"pitch\": 1.0 }] }`:")
        append(SfxCatalog.compactPromptList())
        appendLine()
        appendLine("Sekarang buatkan kode video animasi berdasarkan permintaan saya berikut:")
    }
}
